{
  "name": "opencode-session-handoff",
  "version": "1.1.6",
  "description": "OpenCode plugin for seamless session continuation when context windows fill up",
  "keywords": [
    "context-window",
    "continuation",
    "handoff",
    "opencode",
    "opencode-plugin",
    "session"
  ],
  "homepage": "https://github.com/bristena-op/opencode-session-handoff#readme",
  "bugs": {
    "url": "https://github.com/bristena-op/opencode-session-handoff/issues"
  },
  "license": "MIT",
  "author": "bristena-op",
  "repository": {
    "type": "git",
    "url": "https://github.com/bristena-op/opencode-session-handoff.git"
  },
  "files": [
    "dist",
    "README.md"
  ],
  "type": "module",
  "main": "dist/index.mjs",
  "module": "dist/index.mjs",
  "types": "dist/index.d.mts",
  "exports": {
    ".": {
      "types": "./dist/index.d.mts",
      "import": "./dist/index.mjs"
    }
  },
  "scripts": {
    "format": "oxfmt .",
    "format:check": "oxfmt --check .",
    "lint": "oxlint -c oxlint.json .",
    "lint:fix": "oxlint -c oxlint.json --fix .",
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "test:watch": "vitest",
    "test:coverage": "vitest run --coverage",
    "build": "tsdown",
    "check": "bun run format:check && bun run lint && bun run typecheck && bun run test",
    "prepublishOnly": "bun run check && bun run build",
    "prepare": "husky"
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.1.12"
  },
  "devDependencies": {
    "@commitlint/cli": "^20.3.1",
    "@commitlint/config-conventional": "^20.3.1",
    "@types/bun": "^1.3.6",
    "@types/node": "^25.0.10",
    "husky": "^9.1.7",
    "lint-staged": "^16.2.7",
    "oxfmt": "^0.26.0",
    "oxlint": "^1.41.0",
    "tsdown": "^0.20.1",
    "typescript": "^5.9.3",
    "vitest": "^4.0.18"
  },
  "lint-staged": {
    "*.{ts,js}": [
      "oxfmt"
    ],
    "*.json": [
      "oxfmt"
    ]
  },
  "engines": {
    "node": ">=18.0.0"
  }
}
